  <script>
    (() => {
      const film = document.querySelector('"'.film');
      const video = film.querySelector('video');
      const button = film.querySelector('button');
      const reducedMotion = window.matchMedia('(prefers-reduced-motion: reduce)');
      let wantsPlayback = "'!reducedMotion.matches;
      let failed = false;
      let playRequest = 0;

      const syncControl = () => {
        film.classList.toggle('"'is-playing', "'!video.paused);
        button.setAttribute('"'aria-label', video.paused ? 'Play background film' : 'Pause background film');
      };
      const showPoster = () => {
        video.pause();
        film.classList.remove('has-frame');
      };
      const fail = () => {
        failed = true;
        wantsPlayback = false;
        showPoster();
        film.classList.add('failed');
        button.hidden = true;
      };
      const updatePlayback = async () => {
        const request = ++playRequest;
        if (failed || "'!wantsPlayback || document.hidden) {
          video.pause();
          return;
        }
        try {
          await video.play();
          if (request !== playRequest && (!wantsPlayback || document.hidden)) video.pause();
        } catch {
          // An autoplay policy may reject playback; the poster and play control remain usable.
          syncControl();
        }
      };
      video.addEventListener('"'playing', () => {
        film.classList.add('has-frame');
        syncControl();
      });
      video.addEventListener('pause', syncControl);
      video.addEventListener('error', fail);
      video.querySelector('source').addEventListener('error', fail);
      button.addEventListener('click', () => {
        wantsPlayback = video.paused;
        updatePlayback();
      });
      reducedMotion.addEventListener('change', () => {
        wantsPlayback = "'!reducedMotion.matches;
        if (reducedMotion.matches) showPoster();
        updatePlayback();
      });
      document.addEventListener('"'visibilitychange', updatePlayback);
      button.hidden = false;
      updatePlayback();
    })();
